import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# C++ source for the transposed 1D convolution function declaration and kernel
conv1d_transpose_cpp_source = (
    "torch::Tensor conv1d_transpose_cuda(torch::Tensor x, int in_channels, int out_channels, int kernel_size, int stride, int padding, int dilation);"
)

# CUDA source: naive implementation of transposed 1D convolution
conv1d_transpose_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_conv_kernel(const float* input, const float* output, int B, int C_in, int C_out, int L_in, int stride, int kernel_size, int padding, int dilation) {
    // Naive implementation: each thread writes one element of the output tensor.
}

torch::Tensor conv1d_transpose_cuda(torch::Tensor x, int in_channels, int out_channels, int kernel_size, int stride, int padding, int dilation) {
    auto B = x.size(0);
    auto C_in = x.size(1);
    auto L_in = x.size(2);

    // Compute output length for transposed convolution
    auto L_out = (L_in - 1) * stride + kernel_size * dilation - 2 * padding * dilation + 1;

    // Allocate zero tensor of shape (B, out_channels, L_out)
    torch::Tensor out = torch::zeros({B, out_channels, L_out});

    const int block_size = 256;
    const int num_blocks = (B * out_channels * L_out + block_size - 1) / block_size;

    transposed_conv_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        C_in,
        out_channels,
        L_in,
        stride,
        kernel_size,
        padding,
        dilation
    );

    return out;
}
"""

# Compile the inline CUDA code for transposed convolution
conv1d_transpose_cuda = load_inline(
    name="conv1d_transpose_cuda",
    cpp_sources=conv1d_transpose_cpp_source,
    cuda_sources=conv1d_transpose_cuda_source,
    functions=["conv1d_transpose_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv1d_transpose = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)
        # Attach the custom CUDA operator
        self.conv1d_transpose_cuda = conv1d_transpose_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv1d_transpose_cuda(
            x,
            in_channels=self.conv1d_transpose.in_channels,
            out_channels=self.conv1d_transpose.out_channels,
            kernel_size=self.conv1d_transpose.kernel_size,
            stride=self.conv1d_transpose.stride,
            padding=self.conv1d_transpose.padding,
            dilation=self.conv1d_transpose.dilation
        )
